+        <!-- Live Preview -->
+        <div class="appearance-preview @GetPreviewClasses()">
+            <h4>Preview</h4>
+            <p>This is how your content will look with the selected settings.</p>
+            <div class="preview-card">
+                <strong>Sample Card</strong>
+                <p>Here is some example text to demonstrate the appearance.</p>
+                <button class="btn btn-primary">Sample Button</button>
+            </div>
+        </div>
+
+        <div class="form-actions">
+            <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
+        </div>
+
+        @if (_successMessage is not null)
+        {
+            <div class="toast-message success">@_successMessage</div>
+        }
+    }
+</div>
+
+@code {
+    private bool _loading = true;
+    private string _theme = "System";
+    private string _fontSize = "Medium";
+    private string _language = "en";
+    private bool _compactMode;
+    private string? _successMessage;
+
+    protected override async Task OnInitializedAsync()
+    {
+        _loading = true;
+        var settings = await SettingsService.GetAppearanceAsync();
+        _theme = settings.Theme;
+        _fontSize = settings.FontSize;
+        _language = settings.Language;
+        _compactMode = settings.CompactMode;
+        _loading = false;
+    }
+
+    private string GetPreviewClasses()
+    {
+        var classes = $"theme-{_theme.ToLowerInvariant()} font-{_fontSize.ToLowerInvariant()}";
+        if (_compactMode) classes += " compact";
+        return classes;
+    }
+
+    private async Task SaveAppearance()
+    {
+        var settings = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
+        await SettingsService.SaveAppearanceAsync(settings);
+        _successMessage = "Appearance saved!";
+        _ = ClearMessageAfterDelay();
+    }
+
+    private async Task ClearMessageAfterDelay()
+    {
+        await Task.Delay(3000);
+        _successMessage = null;
+        await InvokeAsync(StateHasChanged);
+    }
+}
+

toolArgs.file_text:
@page "/settings"
@namespace sv_66a04a1e016840c68379ab4aa530cc41.Components.Pages.Settings
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-page">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="SetActiveSection" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

.settings-page {
    display: flex;
    min-height: 100vh;
    gap: 0;
}

::deep .settings-sidebar {
    display: flex;
    flex-direction: column;
    width: 240px;
    min-height: 100vh;
    background: #f8f9fa;
    border-right: 1px solid #e0e0e0;
    padding: 1rem 0;
}

::deep .sidebar-item {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1.25rem;
    border: none;
    background: transparent;
    cursor: pointer;
    font-size: 0.95rem;
    color: #555;
    text-align: left;
    width: 100%;
    transition: background 0.15s, color 0.15s;
}

::deep .sidebar-item:hover {
    background: #e9ecef;
    color: #333;
}

::deep .sidebar-item.active {
    background: #0d6efd;
    color: #fff;
    font-weight: 600;
}

.settings-content {
    flex: 1;
    padding: 2rem;
    max-width: 800px;
}

::deep .settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    color: #333;
}

::deep .form-group {
    margin-bottom: 1.25rem;
}

::deep .form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #444;
}

::deep .form-control {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
}

::deep .form-control:focus {
    outline: none;
    border-color: #0d6efd;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

::deep .form-actions {
    margin-top: 1.5rem;
    display: flex;
    gap: 0.75rem;
}

::deep .btn {
    padding: 0.5rem 1.25rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    font-weight: 500;
    transition: background 0.15s;
}

::deep .btn-primary {
    background: #0d6efd;
    color: #fff;
}

::deep .btn-primary:hover {
    background: #0b5ed7;
}

::deep .btn-secondary {
    background: #6c757d;
    color: #fff;
}

::deep .btn-secondary:hover {
    background: #5a6268;
}

::deep .btn-danger {
    background: #dc3545;
    color: #fff;
}

::deep .btn-danger:hover {
    background: #c82333;
}

::deep .btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

::deep .toast-message {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

::deep .toast-message.success {
    background: #d1e7dd;
    color: #0f5132;
    border: 1px solid #badbcc;
}

::deep .toast-message.error {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

/* Avatar */
::deep .avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

::deep .avatar-image {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    object-fit: cover;
    background: #dee2e6;
}

::deep .avatar-url {
    font-size: 0.85rem;
    color: #666;
    word-break: break-all;
}

/* Toggles */
::deep .toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    margin-bottom: 1.5rem;
}

::deep .toggle-item {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    cursor: pointer;
}

::deep .toggle-item input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #0d6efd;
}

/* Channels */
::deep .channel-list {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1.5rem;
}

::deep .channel-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

/* Security */
::deep .expandable-panel {
    border: 1px solid #e0e0e0;
    border-radius: 6px;
    margin-bottom: 1.5rem;
    overflow: hidden;
}

::deep .panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.85rem 1rem;
    background: #f8f9fa;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
}

::deep .panel-header:hover {
    background: #e9ecef;
}

::deep .panel-body {
    padding: 1rem;
    border-top: 1px solid #e0e0e0;
}

::deep .security-item {
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 6px;
}

::deep .status-indicator {
    margin-left: 0.75rem;
    padding: 0.2rem 0.6rem;
    border-radius: 12px;
    font-size: 0.75rem;
    font-weight: 600;
}

::deep .status-indicator.enabled {
    background: #d1e7dd;
    color: #0f5132;
}

::deep .status-indicator.disabled {
    background: #f8d7da;
    color: #842029;
}

::deep .text-muted {
    color: #6c757d;
    font-size: 0.85rem;
}

::deep .sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 1.5rem;
}

::deep .sessions-table th,
::deep .sessions-table td {
    padding: 0.65rem 0.85rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
}

::deep .sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    font-size: 0.85rem;
    color: #555;
}

/* Dialog */
::deep .dialog-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

::deep .dialog {
    background: #fff;
    padding: 1.5rem;
    border-radius: 8px;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.15);
}

::deep .dialog h4 {
    margin-top: 0;
}

::deep .dialog-actions {
    margin-top: 1rem;
    display: flex;
    gap: 0.75rem;
    justify-content: flex-end;
}

/* Appearance Preview */
::deep .appearance-preview {
    margin: 1.5rem 0;
    padding: 1.5rem;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    transition: all 0.2s;
}

::deep .appearance-preview.theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

::deep .appearance-preview.theme-light {
    background: #ffffff;
    color: #333;
}

::deep .appearance-preview.theme-system {
    background: #f5f5f5;
    color: #333;
}

::deep .appearance-preview.font-small {
    font-size: 0.8rem;
}

::deep .appearance-preview.font-medium {
    font-size: 1rem;
}

::deep .appearance-preview.font-large {
    font-size: 1.2rem;
}

::deep .appearance-preview.compact {
    padding: 0.75rem;
    line-height: 1.2;
}

::deep .preview-card {
    margin-top: 1rem;
    padding: 1rem;
    border: 1px solid currentColor;
    border-radius: 6px;
    opacity: 0.8;
}

/* Radio group */
::deep .radio-group {
    display: flex;
    gap: 1.25rem;
}

::deep .radio-group label {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    cursor: pointer;
    font-weight: normal;
}

